/**
 * The application lifecycle phase, as the host reports it.
 */

public enum AppPhase: Equatable, Hashable {
    
    case launching
    case active
    case inactive
    case background
    case terminated





}

#if compiler(>=6)
extension AppPhase: Sendable {}
#endif

