    typealias SwiftType = ErrorKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ErrorKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .invalid
        
        case 2: return .notFound
        
        case 3: return .unavailable
        
        case 4: return .interrupted
        
        case 5: return .cancelled
        
        case 6: return .needsUser
        
        case 7: return .corrupt
        
        case 8: return .newerData
        
        case 9: return .shutDown
        
        case 10: return .`internal`
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ErrorKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .invalid:
            writeInt(&buf, Int32(1))
        
        
        case .notFound:
            writeInt(&buf, Int32(2))
        
        
        case .unavailable:
            writeInt(&buf, Int32(3))
        
        
        case .interrupted:
            writeInt(&buf, Int32(4))
        
        
        case .cancelled:
            writeInt(&buf, Int32(5))
        
        
        case .needsUser:
            writeInt(&buf, Int32(6))
        
        
        case .corrupt:
            writeInt(&buf, Int32(7))
        
        
        case .newerData:
            writeInt(&buf, Int32(8))
        
        
        case .shutDown:
            writeInt(&buf, Int32(9))
        
        
        case .`internal`:
            writeInt(&buf, Int32(10))
        
        }
    }
}


