/**
 * What the runtime tells the host. The same in every app; an app with
 * domain events of its own keeps a second stream.
 */

public enum RuntimeEvent: Equatable, Hashable {
    
    /**
     * A command committed. Re-query whatever is on screen.
     */
    case changed(revision: UInt64
    )
    /**
     * The host reported a phase. `resumed` is true on return from the
     * background: refresh, and restart work the background stopped.
     */
    case phaseChanged(phase: AppPhase, resumed: Bool
    )
    /**
     * This stream fell behind and missed `count` events. Re-read everything.
     */
    case eventsDropped(count: UInt64
    )





}

#if compiler(>=6)
extension RuntimeEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRuntimeEvent: FfiConverterRustBuffer {
    typealias SwiftType = RuntimeEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RuntimeEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .changed(revision: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 2: return .phaseChanged(phase: try FfiConverterTypeAppPhase.read(from: &buf), resumed: try FfiConverterBool.read(from: &buf)
        )
        
        case 3: return .eventsDropped(count: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RuntimeEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .changed(revision):
            writeInt(&buf, Int32(1))
            FfiConverterUInt64.write(revision, into: &buf)
            
        
        case let .phaseChanged(phase,resumed):
            writeInt(&buf, Int32(2))
            FfiConverterTypeAppPhase.write(phase, into: &buf)
            FfiConverterBool.write(resumed, into: &buf)
            
        
        case let .eventsDropped(count):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(count, into: &buf)
            
        }
    }
}


